-- Упражнения книги 19, глава 18 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 18, 'la18-degraded-maps', 0, 'func', 'Деградировавшие карты multipath', 'Напишите функцию degraded_maps(text): text — вывод multipath -ll. Заголовок карты начинается в первой колонке и содержит токен dm-N (например, «mpatha (3600...) dm-2 LIO-ORG,disk1» или, если алиаса нет, «3600... dm-3 NETAPP,LUN C-Mode»); имя карты — первый токен заголовка. Строка пути содержит H:C:T:L, имя диска, major:minor и три состояния: dm-состояние, состояние проверки (может состоять из двух слов, например «i/o pending») и онлайн-состояние, перед ней могут стоять символы дерева «|», «`», «-», «+» и пробелы. Путь здоров, только если dm-состояние active, проверка ready или ghost и онлайн-состояние running; всё остальное (failed, faulty, shaky, i/o pending, delayed, offline...) нездорово. Все прочие строки (size=..., строки групп, предупреждения) игнорируйте. Верните словарь {имя карты: [имена нездоровых дисков в порядке появления]} только для карт, где есть хотя бы один нездоровый путь.', 'def degraded_maps(text):
    pass
', 'Два регулярных выражения: заголовок (токен dm-N после необязательного WWID в скобках) и путь (четыре числа через двоеточие, диск, major:minor, затем три состояния; середину берите нежадно).', '{"func": "degraded_maps", "tests": [{"args": ["mpatha (36001405aa11bb22cc33dd44ee55ff660) dm-2 LIO-ORG,disk1\nsize=100G features=''1 queue_if_no_path'' hwhandler=''1 alua'' wp=rw\n|-+- policy=''service-time 0'' prio=50 status=active\n| |- 5:0:0:1 sdb 8:16 active ready running\n| `- 6:0:0:1 sdd 8:48 active ready running\n`-+- policy=''service-time 0'' prio=10 status=enabled\n  `- 7:0:0:1 sdc 8:32 active ready running\n"], "expected": {}}, {"args": ["mpatha (36001405aa11bb22cc33dd44ee55ff660) dm-2 LIO-ORG,disk1\nsize=100G features=''1 queue_if_no_path'' hwhandler=''1 alua'' wp=rw\n|-+- policy=''service-time 0'' prio=50 status=active\n| |- 5:0:0:1 sdb 8:16 active ready running\n| `- 6:0:0:1 sdd 8:48 active ready running\n`-+- policy=''service-time 0'' prio=10 status=enabled\n  `- 7:0:0:1 sdc 8:32 active ready running\n36001405cc77dd88ee99ff00aa11bb220 dm-3 NETAPP,LUN C-Mode\nsize=500G features=''0'' hwhandler=''1 alua'' wp=rw\n|-+- policy=''service-time 0'' prio=50 status=active\n| |- 5:0:1:2 sde 8:64 active ready running\n| `- 6:0:1:2 sdf 8:80 failed faulty offline\n`-+- policy=''service-time 0'' prio=10 status=enabled\n  |- 5:0:2:2 sdg 8:96 active ready running\n  `- 6:0:2:2 sdh 8:112 active i/o pending running\n"], "expected": {"36001405cc77dd88ee99ff00aa11bb220": ["sdf", "sdh"]}}, {"args": ["mpathb (3600a09803830476f6a2b4f6e7a6d4b31) dm-4 NETAPP,LUN C-Mode\nsize=1.0T features=''3 queue_if_no_path pg_init_retries 50'' hwhandler=''1 alua'' wp=rw\n|-+- policy=''service-time 0'' prio=50 status=active\n| `- 3:0:0:0 sdb 8:16 active ready running\n`-+- policy=''service-time 0'' prio=10 status=enabled\n  `- 4:0:0:0 sdc 8:32 active ghost running\n"], "expected": {}}, {"args": ["Nov 03 10:02:15 | /etc/multipath.conf line 12, invalid keyword: foo\nmpathc (360014050000000000000000000000001) dm-5 LIO-ORG,disk2\nsize=20G features=''0'' hwhandler=''0'' wp=rw\n`-+- policy=''round-robin 0'' prio=1 status=active\n  |- 8:0:0:3 sdi 8:128 active faulty running\n  |- 9:0:0:3 sdj 8:144 failed ready running\n  `- 10:0:0:3 sdk 8:160 active ready running\n"], "expected": {"mpathc": ["sdi", "sdj"]}}, {"args": ["mpatha (36001405aa11bb22cc33dd44ee55ff660) dm-2 LIO-ORG,disk1\nsize=100G features=''1 queue_if_no_path'' hwhandler=''1 alua'' wp=rw\n|-+- policy=''service-time 0'' prio=50 status=active\n| |- 5:0:0:1 sdb 8:16 active ready running\n| `- 6:0:0:1 sdd 8:48 active ready running\n`-+- policy=''service-time 0'' prio=10 status=enabled\n  `- 7:0:0:1 sdc 8:32 active ready running\nNov 03 10:02:15 | /etc/multipath.conf line 12, invalid keyword: foo\nmpathc (360014050000000000000000000000001) dm-5 LIO-ORG,disk2\nsize=20G features=''0'' hwhandler=''0'' wp=rw\n`-+- policy=''round-robin 0'' prio=1 status=active\n  |- 8:0:0:3 sdi 8:128 active faulty running\n  |- 9:0:0:3 sdj 8:144 failed ready running\n  `- 10:0:0:3 sdk 8:160 active ready running\nmpathd (360014050000000000000000000000002) dm-6 LIO-ORG,disk3\nsize=5G features=''0'' hwhandler=''0'' wp=rw\n`-+- policy=''service-time 0'' prio=0 status=enabled\n  |- 8:0:0:4 sdl 8:176 failed faulty offline\n  `- 9:0:0:4 sdm 8:192 failed faulty offline\n"], "expected": {"mpathc": ["sdi", "sdj"], "mpathd": ["sdl", "sdm"]}}, {"args": [""], "expected": {}}, {"args": ["No multipath maps\n"], "expected": {}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 18, 'la18-active-paths', 1, 'func', 'Какие пути несут ввод-вывод', 'Напишите функцию active_paths(policy, paths, failback, events). paths — список [имя, приоритет], сначала все пути работают. Группы путей: policy ''multibus'' — одна группа из всех путей в порядке списка; ''failover'' — по одной группе на путь; ''group_by_prio'' — по группе на каждое значение приоритета, внутри группы пути в порядке списка. Группы (кроме multibus) упорядочены по убыванию приоритета, при равенстве — в порядке списка. Работает ровно одна группа (active): сначала первая в порядке групп. events — список [t, имя, ''down'' или ''up''], обрабатываются по порядку. После каждого события: если в active-группе не осталось работающих путей, active становится первой группой, где есть работающий путь (если таких нет, работающей группы нет); иначе при failback ''immediate'' active становится первой группой с работающим путём (возврат к лучшей), а при ''manual'' остаётся прежней. Верните список [t, список работающих путей active-группы в порядке групп] для каждого события (пустой список, если группы нет).', 'def active_paths(policy, paths, failback, events):
    pass
', 'Постройте список групп один раз; для каждого события обновите множество работающих путей и пересчитайте индекс active-группы по правилам.', '{"func": "active_paths", "tests": [{"args": ["failover", [["sdb", 50], ["sdc", 10]], "manual", [[1, "sdb", "down"], [2, "sdb", "up"], [3, "sdc", "down"]]], "expected": [[1, ["sdc"]], [2, ["sdc"]], [3, ["sdb"]]]}, {"args": ["failover", [["sdb", 50], ["sdc", 10]], "immediate", [[1, "sdb", "down"], [2, "sdb", "up"], [3, "sdc", "down"]]], "expected": [[1, ["sdc"]], [2, ["sdb"]], [3, ["sdb"]]]}, {"args": ["multibus", [["a", 1], ["b", 1], ["c", 1]], "manual", [[1, "a", "down"], [2, "b", "down"], [3, "c", "down"], [4, "b", "up"]]], "expected": [[1, ["b", "c"]], [2, ["c"]], [3, []], [4, ["b"]]]}, {"args": ["group_by_prio", [["a", 50], ["b", 50], ["c", 10], ["d", 10]], "manual", [[1, "a", "down"], [2, "b", "down"], [3, "a", "up"], [4, "c", "down"]]], "expected": [[1, ["b"]], [2, ["c", "d"]], [3, ["c", "d"]], [4, ["d"]]]}, {"args": ["group_by_prio", [["a", 50], ["b", 50], ["c", 10], ["d", 10]], "immediate", [[1, "a", "down"], [2, "b", "down"], [3, "a", "up"], [4, "c", "down"]]], "expected": [[1, ["b"]], [2, ["c", "d"]], [3, ["a"]], [4, ["a"]]]}, {"args": ["failover", [["x", 5]], "manual", [[1, "x", "down"], [2, "x", "up"]]], "expected": [[1, []], [2, ["x"]]]}, {"args": ["failover", [["p", 10], ["q", 10]], "manual", [[5, "p", "down"], [9, "q", "down"], [12, "q", "up"]]], "expected": [[5, ["q"]], [9, []], [12, ["q"]]]}, {"args": ["failover", [["p", 10]], "manual", []], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 18, 'la18-queueing', 2, 'func', 'Очередь при потере всех путей', 'Напишите функцию io_outcomes(no_path_retry, polling_interval, t_down, t_up, ios). Все пути карты недоступны с момента t_down (включительно) до t_up (не включая; None — путь так и не вернулся). ios — моменты, когда приходят запросы. no_path_retry: строка ''fail'' (очереди нет), строка ''queue'' (очередь без ограничения) или число/строка с числом N: очередь живёт N интервалов опроса, то есть до момента deadline = t_down + N * polling_interval, после чего отключается, и поставленные в неё запросы получают ошибки. Для каждого запроса верните: ''ok'' — пришёл до t_down или в момент t_up и позже; ''delayed'' — пришёл во время потери, был поставлен в очередь и завершится после возврата пути (путь вернулся не позже deadline, либо очередь бесконечна); ''failed'' — запрос получит ошибку (пришёл в момент deadline или позже, либо очередь отключится раньше возврата пути, либо режим ''fail''); ''hung'' — очередь бесконечна, а путь не вернулся. N = 0 равносильно ''fail''.', 'def io_outcomes(no_path_retry, polling_interval, t_down, t_up, ios):
    pass
', 'Сначала вычислите deadline (для ''queue'' его нет), потом по каждому моменту разберите случаи: вне потери, после deadline, до deadline.', '{"func": "io_outcomes", "tests": [{"args": ["fail", 5, 10, 100, [5, 10, 11, 100, 120]], "expected": ["ok", "failed", "failed", "ok", "ok"]}, {"args": [12, 5, 0, null, [0, 30, 59, 60, 61]], "expected": ["failed", "failed", "failed", "failed", "failed"]}, {"args": [12, 5, 0, 50, [0, 30, 49, 50, 60]], "expected": ["delayed", "delayed", "delayed", "ok", "ok"]}, {"args": ["12", 5, 0, 60, [10, 60]], "expected": ["delayed", "ok"]}, {"args": [12, 5, 0, 70, [10, 59, 60, 65, 70]], "expected": ["failed", "failed", "failed", "failed", "ok"]}, {"args": ["queue", 5, 10, null, [9, 10, 5000]], "expected": ["ok", "hung", "hung"]}, {"args": ["queue", 5, 10, 4000, [9, 10, 3999, 4000]], "expected": ["ok", "delayed", "delayed", "ok"]}, {"args": [0, 5, 20, 40, [19, 20, 30]], "expected": ["ok", "failed", "failed"]}, {"args": [3, 10, 100, 125, [100, 120, 130]], "expected": ["delayed", "delayed", "ok"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 18, 'la18-path-selector', 3, 'func', 'Выбор пути селектором', 'Напишите функцию pick_paths(selector, repeat, paths, events). paths — имена путей группы по порядку, все работают. events — список событий: [''io'', размер] — новый запрос (нужно выбрать путь) и [''done'', путь, размер] — завершился запрос этого размера на этом пути. Селекторы: ''round-robin'' — берёт текущий путь по кругу и переходит к следующему после каждых repeat запросов (первый путь — первый в списке); ''queue-length'' — путь с наименьшим числом запросов в полёте; ''service-time'' — путь с наименьшим суммарным размером запросов в полёте в байтах (все пути считаются одинаково быстрыми, размер нового запроса учитывать не нужно). При равенстве queue-length и service-time выбирают первый из равных в списке. Выбранный путь получает запрос в полёте; ''done'' уменьшает счётчики. Верните список выбранных путей для событий ''io'' по порядку.', 'def pick_paths(selector, repeat, paths, events):
    pass
', 'Храните для каждого пути число запросов и сумму байт; для round-robin держите индекс и счётчик запросов на текущем пути; min() по списку возвращает первый минимальный.', '{"func": "pick_paths", "tests": [{"args": ["round-robin", 1, ["sdb", "sdc", "sdd"], [["io", 4], ["io", 4], ["io", 4], ["io", 4]]], "expected": ["sdb", "sdc", "sdd", "sdb"]}, {"args": ["round-robin", 2, ["sdb", "sdc"], [["io", 4], ["io", 4], ["io", 4], ["io", 4], ["io", 4]]], "expected": ["sdb", "sdb", "sdc", "sdc", "sdb"]}, {"args": ["queue-length", 1, ["a", "b"], [["io", 512], ["io", 4], ["io", 4], ["done", "a", 512], ["io", 4]]], "expected": ["a", "b", "a", "a"]}, {"args": ["service-time", 1, ["a", "b"], [["io", 512], ["io", 4], ["io", 4], ["io", 4]]], "expected": ["a", "b", "b", "b"]}, {"args": ["queue-length", 1, ["a", "b"], [["io", 512], ["io", 4], ["io", 4], ["io", 4]]], "expected": ["a", "b", "a", "b"]}, {"args": ["service-time", 1, ["a", "b", "c"], [["io", 8], ["io", 8], ["io", 8], ["done", "b", 8], ["io", 1], ["io", 100]]], "expected": ["a", "b", "c", "b", "b"]}, {"args": ["round-robin", 3, ["x"], [["io", 1], ["io", 1]]], "expected": ["x", "x"]}, {"args": ["service-time", 1, ["a", "b"], []], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 18, 'la18-missing-sessions', 4, 'func', 'Недостающие iSCSI-сессии', 'Напишите функцию missing_sessions(text, expected). text — вывод iscsiadm -m session: строки вида «tcp: [1] 10.0.0.1:3260,1 iqn... (non-flash)» (в старых версиях без двоеточия после tcp и без хвоста в скобках; IPv6-адреса в квадратных скобках: «[fd00::1]:3260,1»); сообщение «iscsiadm: No active sessions.» не содержит сессий. Номер после запятой — тег группы порталов, его при сравнении отбрасывают. expected — словарь {имя таргета: [порталы]}, портал записан как «адрес:порт» или без порта (тогда порт 3260; для IPv6 — «[адрес]»). Верните отсортированный список пар [таргет, портал] (портал с портом), для которых нет ни одной сессии с тем же таргетом и порталом. Одинаковые пары в результате не повторяются.', 'def missing_sessions(text, expected):
    pass
', 'Строка сессии: split() даёт [драйвер, [sid], портал,тег, таргет, ...]; тег отрезайте через rsplit('','', 1). Порт по умолчанию добавляйте к ожидаемым порталам до сравнения.', '{"func": "missing_sessions", "tests": [{"args": ["tcp: [1] 10.0.0.1:3260,1 iqn.2003-01.org.linux-iscsi.san1:sn.a1 (non-flash)\ntcp: [2] 10.0.1.1:3260,2 iqn.2003-01.org.linux-iscsi.san1:sn.a1 (non-flash)\ntcp: [3] 10.0.0.2:3260,1 iqn.2003-01.org.linux-iscsi.san1:sn.b2 (non-flash)\n", {"iqn.2003-01.org.linux-iscsi.san1:sn.a1": ["10.0.0.1:3260", "10.0.1.1"], "iqn.2003-01.org.linux-iscsi.san1:sn.b2": ["10.0.0.2"]}], "expected": []}, {"args": ["tcp: [1] 10.0.0.1:3260,1 iqn.2003-01.org.linux-iscsi.san1:sn.a1 (non-flash)\ntcp: [2] 10.0.1.1:3260,2 iqn.2003-01.org.linux-iscsi.san1:sn.a1 (non-flash)\ntcp: [3] 10.0.0.2:3260,1 iqn.2003-01.org.linux-iscsi.san1:sn.b2 (non-flash)\n", {"iqn.2003-01.org.linux-iscsi.san1:sn.b2": ["10.0.0.2:3260", "10.0.1.2:3260"], "iqn.2003-01.org.linux-iscsi.san1:sn.a1": ["10.0.0.1", "10.0.2.1"]}], "expected": [["iqn.2003-01.org.linux-iscsi.san1:sn.a1", "10.0.2.1:3260"], ["iqn.2003-01.org.linux-iscsi.san1:sn.b2", "10.0.1.2:3260"]]}, {"args": ["tcp: [1] 10.0.0.1:3260,1 iqn.2003-01.org.linux-iscsi.san1:sn.a1 (non-flash)\ntcp: [2] 10.0.1.1:3260,2 iqn.2003-01.org.linux-iscsi.san1:sn.a1 (non-flash)\ntcp: [3] 10.0.0.2:3260,1 iqn.2003-01.org.linux-iscsi.san1:sn.b2 (non-flash)\n", {"iqn.2003-01.org.linux-iscsi.san1:sn.b2": ["10.0.1.1:3260"]}], "expected": [["iqn.2003-01.org.linux-iscsi.san1:sn.b2", "10.0.1.1:3260"]]}, {"args": ["tcp: [4] [fd00:10::1]:3260,1 iqn.2005-10.org.example:array7 (non-flash)\ntcp: [5] 192.168.5.10:3260,1 iqn.2005-10.org.example:array7 (non-flash)\n", {"iqn.2005-10.org.example:array7": ["[fd00:10::1]", "[fd00:10::2]:3260", "192.168.5.10:3261"]}], "expected": [["iqn.2005-10.org.example:array7", "192.168.5.10:3261"], ["iqn.2005-10.org.example:array7", "[fd00:10::2]:3260"]]}, {"args": ["tcp [2] 10.15.84.19:3260,2 iqn.1992-08.com.netapp:sn.33615311\ntcp [3] 10.15.85.19:3260,3 iqn.1992-08.com.netapp:sn.33615311\n", {"iqn.1992-08.com.netapp:sn.33615311": ["10.15.84.19:3260", "10.15.85.19:3260", "10.15.86.19:3260"]}], "expected": [["iqn.1992-08.com.netapp:sn.33615311", "10.15.86.19:3260"]]}, {"args": ["iscsiadm: No active sessions.\n", {"iqn.x:y": ["10.0.0.1", "10.0.0.1:3260"]}], "expected": [["iqn.x:y", "10.0.0.1:3260"]]}, {"args": ["tcp: [1] 10.0.0.1:3260,1 iqn.2003-01.org.linux-iscsi.san1:sn.a1 (non-flash)\ntcp: [2] 10.0.1.1:3260,2 iqn.2003-01.org.linux-iscsi.san1:sn.a1 (non-flash)\ntcp: [3] 10.0.0.2:3260,1 iqn.2003-01.org.linux-iscsi.san1:sn.b2 (non-flash)\n", {}], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 18, 'la18-session-health', 5, 'func', 'Здоровье iSCSI-сессий', 'Напишите функцию session_health(text). text — вывод iscsiadm -m session -P 3 (или -P 1): строки с табуляциями и произвольными служебными строками. Строка «Target: <имя> (non-flash)» задаёт текущий таргет (суффикс в скобках отбросьте); под одним заголовком Target может идти несколько сессий. Каждая строка «Current Portal: адрес:порт,тег» начинает новую сессию (портал — без тега); дальше в её блоке идут «SID: n», «iSCSI Connection State: ...», «iSCSI Session State: ...» и для каждого диска «Attached scsi disk sdX<табуляции>State: ...». Вердикт сессии: ''connection: <состояние>'', если состояние соединения не «LOGGED IN»; иначе ''session: <состояние>'', если состояние сессии не «LOGGED_IN»; иначе ''disk <имя>: <состояние>'' для первого диска, у которого состояние не «running»; иначе ''ok''. Верните список [sid (число), таргет, портал, вердикт], отсортированный по sid.', 'def session_health(text):
    pass
', 'Идите по строкам, делая strip(); на «Current Portal:» создавайте запись, остальные поля дописывайте в последнюю запись. Диск ловится регулярным выражением по «Attached scsi disk».', '{"func": "session_health", "tests": [{"args": ["iSCSI Transport Class version 2.0-870\nversion 2.1.8\nTarget: iqn.2003-01.org.linux-iscsi.san1:sn.a1 (non-flash)\n\tCurrent Portal: 10.0.0.1:3260,1\n\tPersistent Portal: 10.0.0.1:3260,1\n\t\t**********\n\t\tInterface:\n\t\t**********\n\t\tIface Name: default\n\t\tIface Transport: tcp\n\t\tIface Initiatorname: iqn.1994-05.com.redhat:7a9c1f\n\t\tIface IPaddress: 10.0.0.10\n\t\tIface HWaddress: <empty>\n\t\tIface Netdev: <empty>\n\t\tSID: 1\n\t\tiSCSI Connection State: LOGGED IN\n\t\tiSCSI Session State: LOGGED_IN\n\t\tInternal iscsid Session State: NO CHANGE\n\t\t*********\n\t\tTimeouts:\n\t\t*********\n\t\tRecovery Timeout: 120\n\t\tTarget Reset Timeout: 30\n\t\tLUN Reset Timeout: 30\n\t\tAbort Timeout: 15\n\t\t************************\n\t\tAttached SCSI devices:\n\t\t************************\n\t\tHost Number: 33\tState: running\n\t\tscsi33 Channel 00 Id 0 Lun: 1\n\t\t\tAttached scsi disk sdb\t\tState: running\n\t\tscsi33 Channel 00 Id 0 Lun: 2\n\t\t\tAttached scsi disk sdc\t\tState: running\n\tCurrent Portal: 10.0.1.1:3260,2\n\tPersistent Portal: 10.0.1.1:3260,2\n\t\t**********\n\t\tInterface:\n\t\t**********\n\t\tIface Name: default\n\t\tIface Transport: tcp\n\t\tIface Initiatorname: iqn.1994-05.com.redhat:7a9c1f\n\t\tIface IPaddress: 10.0.0.10\n\t\tIface HWaddress: <empty>\n\t\tIface Netdev: <empty>\n\t\tSID: 2\n\t\tiSCSI Connection State: LOGGED IN\n\t\tiSCSI Session State: LOGGED_IN\n\t\tInternal iscsid Session State: NO CHANGE\n\t\t*********\n\t\tTimeouts:\n\t\t*********\n\t\tRecovery Timeout: 120\n\t\tTarget Reset Timeout: 30\n\t\tLUN Reset Timeout: 30\n\t\tAbort Timeout: 15\n\t\t************************\n\t\tAttached SCSI devices:\n\t\t************************\n\t\tHost Number: 34\tState: running\n\t\tscsi34 Channel 00 Id 0 Lun: 1\n\t\t\tAttached scsi disk sdd\t\tState: running\n\t\tscsi34 Channel 00 Id 0 Lun: 2\n\t\t\tAttached scsi disk sde\t\tState: running\n"], "expected": [[1, "iqn.2003-01.org.linux-iscsi.san1:sn.a1", "10.0.0.1:3260", "ok"], [2, "iqn.2003-01.org.linux-iscsi.san1:sn.a1", "10.0.1.1:3260", "ok"]]}, {"args": ["iSCSI Transport Class version 2.0-870\nversion 2.1.8\nTarget: iqn.2003-01.org.linux-iscsi.san1:sn.a1 (non-flash)\n\tCurrent Portal: 10.0.0.1:3260,1\n\tPersistent Portal: 10.0.0.1:3260,1\n\t\t**********\n\t\tInterface:\n\t\t**********\n\t\tIface Name: default\n\t\tIface Transport: tcp\n\t\tIface Initiatorname: iqn.1994-05.com.redhat:7a9c1f\n\t\tIface IPaddress: 10.0.0.10\n\t\tIface HWaddress: <empty>\n\t\tIface Netdev: <empty>\n\t\tSID: 1\n\t\tiSCSI Connection State: LOGGED IN\n\t\tiSCSI Session State: LOGGED_IN\n\t\tInternal iscsid Session State: NO CHANGE\n\t\t*********\n\t\tTimeouts:\n\t\t*********\n\t\tRecovery Timeout: 120\n\t\tTarget Reset Timeout: 30\n\t\tLUN Reset Timeout: 30\n\t\tAbort Timeout: 15\n\t\t************************\n\t\tAttached SCSI devices:\n\t\t************************\n\t\tHost Number: 33\tState: running\n\t\tscsi33 Channel 00 Id 0 Lun: 1\n\t\t\tAttached scsi disk sdb\t\tState: running\n\tCurrent Portal: 10.0.1.1:3260,2\n\tPersistent Portal: 10.0.1.1:3260,2\n\t\t**********\n\t\tInterface:\n\t\t**********\n\t\tIface Name: default\n\t\tIface Transport: tcp\n\t\tIface Initiatorname: iqn.1994-05.com.redhat:7a9c1f\n\t\tIface IPaddress: 10.0.0.10\n\t\tIface HWaddress: <empty>\n\t\tIface Netdev: <empty>\n\t\tSID: 2\n\t\tiSCSI Connection State: TRANSPORT WAIT\n\t\tiSCSI Session State: FAILED\n\t\tInternal iscsid Session State: NO CHANGE\n\t\t*********\n\t\tTimeouts:\n\t\t*********\n\t\tRecovery Timeout: 120\n\t\tTarget Reset Timeout: 30\n\t\tLUN Reset Timeout: 30\n\t\tAbort Timeout: 15\n\t\t************************\n\t\tAttached SCSI devices:\n\t\t************************\n\t\tHost Number: 34\tState: running\n\t\tscsi34 Channel 00 Id 0 Lun: 1\n\t\t\tAttached scsi disk sdd\t\tState: blocked\nTarget: iqn.2003-01.org.linux-iscsi.san1:sn.b2 (non-flash)\n\tCurrent Portal: 10.0.2.1:3260,1\n\tPersistent Portal: 10.0.2.1:3260,1\n\t\t**********\n\t\tInterface:\n\t\t**********\n\t\tIface Name: default\n\t\tIface Transport: tcp\n\t\tIface Initiatorname: iqn.1994-05.com.redhat:7a9c1f\n\t\tIface IPaddress: 10.0.0.10\n\t\tIface HWaddress: <empty>\n\t\tIface Netdev: <empty>\n\t\tSID: 3\n\t\tiSCSI Connection State: LOGGED IN\n\t\tiSCSI Session State: LOGGED_IN\n\t\tInternal iscsid Session State: NO CHANGE\n\t\t*********\n\t\tTimeouts:\n\t\t*********\n\t\tRecovery Timeout: 120\n\t\tTarget Reset Timeout: 30\n\t\tLUN Reset Timeout: 30\n\t\tAbort Timeout: 15\n\t\t************************\n\t\tAttached SCSI devices:\n\t\t************************\n\t\tHost Number: 35\tState: running\n\t\tscsi35 Channel 00 Id 0 Lun: 1\n\t\t\tAttached scsi disk sdf\t\tState: running\n\t\tscsi35 Channel 00 Id 0 Lun: 2\n\t\t\tAttached scsi disk sdg\t\tState: blocked\n"], "expected": [[1, "iqn.2003-01.org.linux-iscsi.san1:sn.a1", "10.0.0.1:3260", "ok"], [2, "iqn.2003-01.org.linux-iscsi.san1:sn.a1", "10.0.1.1:3260", "connection: TRANSPORT WAIT"], [3, "iqn.2003-01.org.linux-iscsi.san1:sn.b2", "10.0.2.1:3260", "disk sdg: blocked"]]}, {"args": ["Target: iqn.2005-10.org.example:array7 (non-flash)\n\tCurrent Portal: [fd00:10::1]:3260,1\n\tPersistent Portal: [fd00:10::1]:3260,1\n\t\t**********\n\t\tInterface:\n\t\t**********\n\t\tIface Name: default\n\t\tIface Transport: tcp\n\t\tIface Initiatorname: iqn.1994-05.com.redhat:7a9c1f\n\t\tIface IPaddress: 10.0.0.10\n\t\tIface HWaddress: <empty>\n\t\tIface Netdev: <empty>\n\t\tSID: 7\n\t\tiSCSI Connection State: LOGGED IN\n\t\tiSCSI Session State: FAILED\n\t\tInternal iscsid Session State: NO CHANGE\n\t\t*********\n\t\tTimeouts:\n\t\t*********\n\t\tRecovery Timeout: 120\n\t\tTarget Reset Timeout: 30\n\t\tLUN Reset Timeout: 30\n\t\tAbort Timeout: 15\n\t\t************************\n\t\tAttached SCSI devices:\n\t\t************************\n\t\tHost Number: 40\tState: running\n\tCurrent Portal: 192.168.5.10:3260,1\n\tPersistent Portal: 192.168.5.10:3260,1\n\t\t**********\n\t\tInterface:\n\t\t**********\n\t\tIface Name: default\n\t\tIface Transport: tcp\n\t\tIface Initiatorname: iqn.1994-05.com.redhat:7a9c1f\n\t\tIface IPaddress: 10.0.0.10\n\t\tIface HWaddress: <empty>\n\t\tIface Netdev: <empty>\n\t\tSID: 5\n\t\tiSCSI Connection State: LOGGED IN\n\t\tiSCSI Session State: LOGGED_IN\n\t\tInternal iscsid Session State: NO CHANGE\n\t\t*********\n\t\tTimeouts:\n\t\t*********\n\t\tRecovery Timeout: 120\n\t\tTarget Reset Timeout: 30\n\t\tLUN Reset Timeout: 30\n\t\tAbort Timeout: 15\n\t\t************************\n\t\tAttached SCSI devices:\n\t\t************************\n\t\tHost Number: 41\tState: running\n\t\tscsi41 Channel 00 Id 0 Lun: 0\n\t\t\tAttached scsi disk sdh\t\tState: running\n"], "expected": [[5, "iqn.2005-10.org.example:array7", "192.168.5.10:3260", "ok"], [7, "iqn.2005-10.org.example:array7", "[fd00:10::1]:3260", "session: FAILED"]]}, {"args": ["iscsiadm: No active sessions.\n"], "expected": []}, {"args": [""], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 18, 'la18-iqn-check', 6, 'func', 'Проверка имён iSCSI', 'Напишите функцию check_iscsi_names(names): для каждого имени из списка верните одну строку-вердикт, проверяя по порядку. ''length'' — имя пустое или длиннее 223 байт в UTF-8. ''type'' — имя не начинается с «iqn.» и не начинается с «eui.». Для «eui.»: после префикса должно быть ровно 16 шестнадцатеричных цифр (регистр любой), иначе ''eui'', иначе ''ok''. Для «iqn.» (RFC 3720): ''case'' — в имени есть заглавная ASCII-буква; ''chars'' — есть символ вне набора a-z, 0-9, «-», «.», «:»; затем часть до первого двоеточия должна иметь вид «гггг-мм.домен», где месяц 01–12, иначе ''date''; домен (обратное доменное имя) — метки из a-z, 0-9 и «-», разделённые точками, метка не пуста и не начинается и не кончается дефисом, иначе ''domain''; если двоеточие есть, но строка после него пуста — ''suffix''; иначе ''ok''.', 'def check_iscsi_names(names):
    pass
', 'Оформите проверку одного имени отдельной функцией; домен проверьте регулярным выражением fullmatch, дату — match с группами.', '{"func": "check_iscsi_names", "tests": [{"args": [["iqn.2001-04.com.example:storage:diskarrays-sn-a8675309", "iqn.2001-04.com.example", "iqn.2001-04.com.example:storage.tape1.sys1.xyz", "eui.02004567A425678D"]], "expected": ["ok", "ok", "ok", "ok"]}, {"args": [["", "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", "iqn.2001-04.com.example:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa", "iqn.2001-04.com.example:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"]], "expected": ["length", "length", "ok", "length"]}, {"args": [["IQN.2001-04.com.example", "naa.5000c50015ea71ac", "iqn2001-04.com.example"]], "expected": ["type", "type", "type"]}, {"args": [["iqn.2001-13.com.example", "iqn.2001-00.com.example", "iqn.01-04.com.example", "iqn.2001-04", "iqn.:abc"]], "expected": ["date", "date", "date", "date", "date"]}, {"args": [["iqn.2001-04.", "iqn.2001-04..example", "iqn.2001-04.-bad.com", "iqn.2001-04.bad-.com", "iqn.2001-04.com.example."]], "expected": ["domain", "domain", "domain", "domain", "domain"]}, {"args": [["iqn.2001-04.com.Example", "iqn.2001-04.com.exa_mple", "iqn.2001-04.com.example:disk 1", "iqn.2001-04.com.exämple"]], "expected": ["case", "chars", "chars", "chars"]}, {"args": [["iqn.2001-04.com.example:", "iqn.2001-04.com.example:a:b:c", "iqn.2001-04.my-san.example:x-1"]], "expected": ["suffix", "ok", "ok"]}, {"args": [["eui.02004567a425678d", "eui.0200", "eui.02004567A425678G", "eui.02004567A425678D0"]], "expected": ["ok", "eui", "eui", "eui"]}, {"args": [[]], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 18, 'la18-effective-settings', 7, 'func', 'Итоговые настройки multipath.conf', 'Напишите функцию effective_settings(defaults, devices, overrides, multipaths, device, keys). Значение параметра берётся из самого сильного раздела, где оно задано; порядок от слабого к сильному: встроенные значения, defaults, devices, overrides, multipaths. Встроенные значения: path_grouping_policy=''failover'', path_selector=''service-time 0'', failback=''manual'', no_path_retry=''fail'', user_friendly_names=''no'', polling_interval=''5''. defaults, overrides — словари {параметр: значение}. devices — список записей {''vendor'': regex, ''product'': regex, ''set'': словарь} в порядке возрастания приоритета (встроенная таблица оборудования идёт первой); подходят все записи, где re.search(vendor, device[''vendor'']) и re.search(product, device[''product'']) оба находят совпадение, и более поздняя запись побеждает более раннюю. multipaths — словарь {wwid: словарь}, раздел применяется при точном совпадении device[''wwid'']. Верните словарь {ключ: значение или None} для каждого ключа из keys.', 'def effective_settings(defaults, devices, overrides, multipaths, device, keys):
    pass
', 'Начните со словаря встроенных значений и последовательно обновляйте его: defaults, подходящие devices по порядку, overrides, multipaths.get(wwid, {}).', '{"func": "effective_settings", "tests": [{"args": [{}, [], {}, {}, {"vendor": "LIO-ORG", "product": "disk1", "wwid": "3600a"}, ["path_grouping_policy", "failback", "no_path_retry", "rr_weight"]], "expected": {"path_grouping_policy": "failover", "failback": "manual", "no_path_retry": "fail", "rr_weight": null}}, {"args": [{"path_grouping_policy": "multibus", "no_path_retry": "queue"}, [], {}, {}, {"vendor": "LIO-ORG", "product": "disk1", "wwid": "3600a"}, ["path_grouping_policy", "no_path_retry"]], "expected": {"path_grouping_policy": "multibus", "no_path_retry": "queue"}}, {"args": [{"path_grouping_policy": "multibus"}, [{"vendor": "NETAPP", "product": "LUN", "set": {"path_grouping_policy": "group_by_prio", "failback": "immediate"}}], {}, {}, {"vendor": "NETAPP", "product": "LUN C-Mode", "wwid": "3600b"}, ["path_grouping_policy", "failback"]], "expected": {"path_grouping_policy": "group_by_prio", "failback": "immediate"}}, {"args": [{"failback": "10"}, [{"vendor": "NETAPP", "product": ".*", "set": {"failback": "immediate"}}], {"failback": "manual"}, {}, {"vendor": "NETAPP", "product": "LUN C-Mode", "wwid": "3600b"}, ["failback"]], "expected": {"failback": "manual"}}, {"args": [{}, [{"vendor": "NETAPP", "product": ".*", "set": {"no_path_retry": "30", "polling_interval": "10"}}], {"no_path_retry": "12"}, {"3600b": {"no_path_retry": "queue"}, "3600c": {"no_path_retry": "6"}}, {"vendor": "NETAPP", "product": "LUN", "wwid": "3600b"}, ["no_path_retry", "polling_interval"]], "expected": {"no_path_retry": "queue", "polling_interval": "10"}}, {"args": [{}, [{"vendor": "NETAPP", "product": ".*", "set": {"no_path_retry": "30"}}, {"vendor": "NETAPP", "product": "LUN C", "set": {"no_path_retry": "8"}}], {}, {"3600c": {"no_path_retry": "6"}}, {"vendor": "NETAPP", "product": "LUN C-Mode", "wwid": "3600b"}, ["no_path_retry"]], "expected": {"no_path_retry": "8"}}, {"args": [{}, [{"vendor": "NETAPP", "product": ".*", "set": {"no_path_retry": "30"}}], {}, {}, {"vendor": "LIO-ORG", "product": "disk1", "wwid": "3600b"}, ["no_path_retry", "path_selector"]], "expected": {"no_path_retry": "fail", "path_selector": "service-time 0"}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 18, 'la18-blacklist', 8, 'func', 'Чёрный список multipath', 'Напишите функцию usable_devices(config, devices). devices — список словарей {''devnode'', ''wwid'', ''vendor'', ''product''}. config = {''blacklist'': {...}, ''exceptions'': {...}} (оба раздела могут не содержать некоторых ключей); внутри раздела ключи: ''devnode'' — список регулярных выражений для имени устройства, ''wwid'' — список регулярных выражений для WWID, ''device'' — список {''vendor'': regex, ''product'': regex} (устройство подходит, если совпали оба). Совпадение — re.search. Критерии devnode, device и wwid проверяются независимо: критерий исключает устройство, если оно подходит под блэклист этого критерия и не подходит под исключения (blacklist_exceptions) того же критерия. Устройство исключено, если его исключает хотя бы один критерий (исключение по wwid не спасает от блэклиста по devnode). Верните devnode устройств, которые multipath использует, в порядке списка.', 'def usable_devices(config, devices):
    pass
', 'Напишите вспомогательную функцию hit(раздел, критерий, устройство) и для трёх критериев проверяйте «в блэклисте и не в исключениях».', '{"func": "usable_devices", "tests": [{"args": [{}, [{"devnode": "sda", "wwid": "3600a", "vendor": "LSI", "product": "MR9361"}]], "expected": ["sda"]}, {"args": [{"blacklist": {"devnode": ["^sda$", "^(ram|loop)[0-9]+"]}}, [{"devnode": "sda", "wwid": "3600a", "vendor": "LSI", "product": "MR9361"}, {"devnode": "sdb", "wwid": "3600b", "vendor": "LIO-ORG", "product": "disk1"}, {"devnode": "loop3", "wwid": "", "vendor": "", "product": ""}]], "expected": ["sdb"]}, {"args": [{"blacklist": {"wwid": ["^3600a"]}}, [{"devnode": "sda", "wwid": "3600a1", "vendor": "LSI", "product": "MR9361"}, {"devnode": "sdb", "wwid": "3600b1", "vendor": "LIO-ORG", "product": "disk1"}]], "expected": ["sdb"]}, {"args": [{"blacklist": {"device": [{"vendor": "LSI", "product": ".*"}]}}, [{"devnode": "sda", "wwid": "w1", "vendor": "LSI", "product": "MR9361"}, {"devnode": "sdb", "wwid": "w2", "vendor": "LSI-X", "product": "disk"}, {"devnode": "sdc", "wwid": "w3", "vendor": "NETAPP", "product": "LSI"}]], "expected": ["sdc"]}, {"args": [{"blacklist": {"devnode": ["^sd[a-z]"]}, "exceptions": {"devnode": ["^sdc$"]}}, [{"devnode": "sda", "wwid": "w1", "vendor": "A", "product": "B"}, {"devnode": "sdc", "wwid": "w2", "vendor": "A", "product": "B"}]], "expected": ["sdc"]}, {"args": [{"blacklist": {"devnode": [".*"]}, "exceptions": {"wwid": ["^3600b"]}}, [{"devnode": "sda", "wwid": "3600a1", "vendor": "A", "product": "B"}, {"devnode": "sdb", "wwid": "3600b1", "vendor": "A", "product": "B"}]], "expected": []}, {"args": [{"blacklist": {"wwid": [".*"]}, "exceptions": {"wwid": ["^3600b"]}}, [{"devnode": "sda", "wwid": "3600a1", "vendor": "A", "product": "B"}, {"devnode": "sdb", "wwid": "3600b1", "vendor": "A", "product": "B"}]], "expected": ["sdb"]}, {"args": [{"blacklist": {"devnode": ["^sdb$"], "wwid": ["^3600b"]}, "exceptions": {"wwid": ["^3600b"]}}, [{"devnode": "sdb", "wwid": "3600b1", "vendor": "A", "product": "B"}, {"devnode": "sdc", "wwid": "3600b2", "vendor": "A", "product": "B"}]], "expected": ["sdc"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 18, 'la18-friendly-names', 9, 'func', 'Дружественные имена карт', 'Напишите функцию friendly_names(bindings, prefix, aliases, wwids, user_friendly): bindings — текст файла /etc/multipath/bindings (строки «алиас WWID»; всё после «#» — комментарий; пустые и неполные строки пропускаются; при повторе WWID верен первый). aliases — словарь {wwid: алиас} из раздела multipaths. Имя карты для WWID определяется так: алиас из aliases (всегда выигрывает); иначе, если user_friendly равно ''yes'', — привязка из bindings, а если её нет, — новое имя prefix + буквы, где номер id = 1, 2, ... записывается буквами a..z, aa, ab, ... (id 26 — z, id 27 — aa, id 53 — ba) и берётся наименьший id, имя которого ещё не занято: заняты все алиасы из bindings (в том числе пропуски между ними заполняются) и имена, выданные в этом вызове; иначе (user_friendly не ''yes'') — сам WWID. wwids обрабатываются по порядку. Верните словарь {wwid: имя}.', 'def friendly_names(bindings, prefix, aliases, wwids, user_friendly):
    pass
', 'Номер в буквы: while i >= 1: i -= 1; буква = chr(97 + i % 26); i //= 26 (буквы добавляются слева). Множество занятых имён пополняйте при каждой выдаче.', '{"func": "friendly_names", "tests": [{"args": ["# Multipath bindings, Version : 1.0\n# NOTE: this file is automatically maintained by the multipath program.\n# You should not need to edit this file in normal circumstances.\n#\n# Format:\n# alias wwid\n#\n", "mpath", {}, ["36001405aa11bb22cc33dd44ee55ff660", "36001405cc77dd88ee99ff00aa11bb220", "3600a09803830476f6a2b4f6e7a6d4b31"], "yes"], "expected": {"36001405aa11bb22cc33dd44ee55ff660": "mpatha", "36001405cc77dd88ee99ff00aa11bb220": "mpathb", "3600a09803830476f6a2b4f6e7a6d4b31": "mpathc"}}, {"args": ["# Multipath bindings, Version : 1.0\n# NOTE: this file is automatically maintained by the multipath program.\n# You should not need to edit this file in normal circumstances.\n#\n# Format:\n# alias wwid\n#\nmpatha 36001405aa11bb22cc33dd44ee55ff660\nmpathc 36001405cc77dd88ee99ff00aa11bb220\n", "mpath", {}, ["3600a09803830476f6a2b4f6e7a6d4b31", "360014050000000000000000000000001", "36001405aa11bb22cc33dd44ee55ff660"], "yes"], "expected": {"3600a09803830476f6a2b4f6e7a6d4b31": "mpathb", "360014050000000000000000000000001": "mpathd", "36001405aa11bb22cc33dd44ee55ff660": "mpatha"}}, {"args": ["# Multipath bindings, Version : 1.0\n# NOTE: this file is automatically maintained by the multipath program.\n# You should not need to edit this file in normal circumstances.\n#\n# Format:\n# alias wwid\n#\nmpatha 36001405aa11bb22cc33dd44ee55ff660\n", "mpath", {"36001405cc77dd88ee99ff00aa11bb220": "data1"}, ["36001405aa11bb22cc33dd44ee55ff660", "36001405cc77dd88ee99ff00aa11bb220", "3600a09803830476f6a2b4f6e7a6d4b31"], "yes"], "expected": {"36001405aa11bb22cc33dd44ee55ff660": "mpatha", "36001405cc77dd88ee99ff00aa11bb220": "data1", "3600a09803830476f6a2b4f6e7a6d4b31": "mpathb"}}, {"args": ["# Multipath bindings, Version : 1.0\n# NOTE: this file is automatically maintained by the multipath program.\n# You should not need to edit this file in normal circumstances.\n#\n# Format:\n# alias wwid\n#\nmpatha 36001405aa11bb22cc33dd44ee55ff660\n", "mpath", {"36001405cc77dd88ee99ff00aa11bb220": "data1"}, ["36001405aa11bb22cc33dd44ee55ff660", "36001405cc77dd88ee99ff00aa11bb220", "3600a09803830476f6a2b4f6e7a6d4b31"], "no"], "expected": {"36001405aa11bb22cc33dd44ee55ff660": "36001405aa11bb22cc33dd44ee55ff660", "36001405cc77dd88ee99ff00aa11bb220": "data1", "3600a09803830476f6a2b4f6e7a6d4b31": "3600a09803830476f6a2b4f6e7a6d4b31"}}, {"args": ["# Multipath bindings, Version : 1.0\n# NOTE: this file is automatically maintained by the multipath program.\n# You should not need to edit this file in normal circumstances.\n#\n# Format:\n# alias wwid\n#\nmpatha 360014050000000000000000000000001\nmpathb 360014050000000000000000000000002\nmpathc 360014050000000000000000000000003\nmpathd 360014050000000000000000000000004\nmpathe 360014050000000000000000000000005\nmpathf 360014050000000000000000000000006\nmpathg 360014050000000000000000000000007\nmpathh 360014050000000000000000000000008\nmpathi 360014050000000000000000000000009\nmpathj 360014050000000000000000000000010\nmpathk 360014050000000000000000000000011\nmpathl 360014050000000000000000000000012\nmpathm 360014050000000000000000000000013\nmpathn 360014050000000000000000000000014\nmpatho 360014050000000000000000000000015\nmpathp 360014050000000000000000000000016\nmpathq 360014050000000000000000000000017\nmpathr 360014050000000000000000000000018\nmpaths 360014050000000000000000000000019\nmpatht 360014050000000000000000000000020\nmpathu 360014050000000000000000000000021\nmpathv 360014050000000000000000000000022\nmpathw 360014050000000000000000000000023\nmpathx 360014050000000000000000000000024\nmpathy 360014050000000000000000000000025\nmpathz 360014050000000000000000000000026\n", "mpath", {}, ["36001405aa11bb22cc33dd44ee55ff660", "36001405cc77dd88ee99ff00aa11bb220"], "yes"], "expected": {"36001405aa11bb22cc33dd44ee55f